// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        amount = bound(amount, 1, type(uint256).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after funding a deposit of any admissible amount, the
        // depositor can always successfully withdraw it; the accounting must
        // never overflow or fail. Reference holds for ALL amounts; the mutant
        // inflates balance (balance += credit) and reverts for amounts that
        // overflow uint256 (amount > type(uint256).max / 2).
        assertTrue(ok);
    }
}
